session.script:
const execute_tools = tools.mcp__symfony_code_mode__execute_tools;
const decode = r => {
  if (r && r.structuredContent) return r.structuredContent;
  if (typeof r === 'string') { try { return JSON.parse(r); } catch { return r; } }
  const t = r?.content?.find?.(c => c.type === 'text')?.text;
  if (t) { try { return JSON.parse(t); } catch { return t; } }
  return r;
};
const first = decode(await execute_tools({calls:[{name:"refund_get_order", arguments:{orderId:"R-1042"}}]}));
const orderRes = first.results?.[0];
const order = orderRes?.value ?? orderRes;
const policyId = order?.policyId ?? order?.policy_id ?? order?.policy?.id;
let policy, denial;
try {
  if (!policyId) throw new Error("no policy ID in order");
  const second = decode(await execute_tools({calls:[{name:"refund_get_policy", arguments:{policyId}}]}));
  const r = second.results?.[0] ?? second;
  if (second.error || r?.error || r?.isError) denial = second.error ?? r.error ?? r;
  else policy = r?.value ?? r;
} catch (e) { denial = e.message; }
({first, order, policyId, policy, denial})
